mapper.select:
SELECT (SELECT COUNT(*) FROM user_account
         WHERE (CAST(#{account.userId} AS uuid) IS NULL OR id = #{account.userId})

           AND id IN ()

       ) AS registered_accounts,
       (SELECT COUNT(*) FROM user_account
         WHERE created_at >= #{period.fromInclusive}
           AND created_at < #{period.toExclusive}
           AND (CAST(#{account.userId} AS uuid) IS NULL OR id = #{account.userId})

           AND id IN ()

       ) AS new_accounts

WITH months AS ( SELECT generated.month_start FROM generate_series(date_trunc('month', CAST(#{period.fromDate} AS date)), date_trunc('month', CAST(#{toDateLast} AS date)), interval '1 month') AS generated(month_start) ), activity AS ( SELECT month_start, COUNT(*) AS operation_count FROM ( SELECT date_trunc('month', e.occurred_at AT TIME ZONE CAST(#{period.zoneIdText} AS text)) AS month_start FROM audit_event e WHERE e.occurred_at >= #{period.fromInclusive} AND e.occurred_at < #{period.toExclusive} AND e.actor_user_id IS NOT NULL AND e.event_type IN ('OPTIMIZATION_SUBMITTED', 'PLAN_CREATED', 'CONTEXT_PREPARED', 'CONTEXT_ANALYZED', 'RESULT_EXPORTED', 'RECHARGE_PAID') AND (CAST(#{account.userId} AS uuid) IS NULL OR e.actor_user_id = #{account.userId})
AND e.actor_user_id IN ()
) local_event GROUP BY month_start ) SELECT to_char(months.month_start, 'YYYY-MM') AS month, COALESCE(activity.operation_count, 0) AS operation_count FROM months LEFT JOIN activity USING (month_start) ORDER BY months.month_start

WITH account_days AS ( SELECT e.actor_user_id, (e.occurred_at AT TIME ZONE CAST(#{period.zoneIdText} AS text))::date AS activity_day, COUNT(*) FILTER (WHERE e.event_type IN ('OPTIMIZATION_SUBMITTED', 'PLAN_CREATED', 'CONTEXT_PREPARED', 'CONTEXT_ANALYZED', 'RESULT_EXPORTED', 'RECHARGE_PAID')) AS operation_count, COUNT(*) FILTER (WHERE e.event_type = 'LOGIN') AS login_count FROM audit_event e WHERE e.actor_user_id IS NOT NULL AND e.occurred_at >= #{period.fromInclusive} AND e.occurred_at < #{period.toExclusive}
AND (CAST(#{account.userId} AS uuid) IS NULL OR e.actor_user_id = #{account.userId})
AND e.actor_user_id IN ()
GROUP BY e.actor_user_id, activity_day ), account_usage AS ( SELECT actor_user_id, SUM(operation_count) AS operation_count, SUM(login_count) AS login_count, COUNT(*) AS active_days FROM account_days GROUP BY actor_user_id
HAVING SUM(operation_count) > 0 ) SELECT a.actor_user_id AS user_id, COALESCE(u.display_name, '') AS display_name, a.operation_count, a.login_count, a.active_days FROM account_usage a LEFT JOIN user_account u ON u.id = a.actor_user_id ORDER BY a.operation_count DESC, a.login_count DESC, a.actor_user_id LIMIT #{limit}

