WHERE e.actor_user_id IS NOT NULL
  AND e.occurred_at >= #{fromInclusive}
  AND e.occurred_at < #{toExclusive}
  AND (CAST(#{account.userId} AS uuid) IS NULL OR e.actor_user_id = #{account.userId})

  AND e.actor_user_id IN ()

  AND (CAST(#{eventType,jdbcType=VARCHAR} AS text) IS NULL OR e.event_type = #{eventType})
